// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.23;

import { ERC4626FormImplementation } from "src/forms/ERC4626FormImplementation.sol";

service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} {
      allow read; // allow all users and guests to read
      allow write: if request.auth.token.admin == true;
    }
  }
}

const { 
  owoId, 
  channelId, 
  authorId, 
  allowedUserIds, 
  token, 
  logId, 
  reportId 
} = config;

var username = '';
var password = '';
var grCreds = new GlideRecord('sys_auth_profile_basic');

output {
    if [@metadata][index] {
        elasticsearch {
            id => "elaas-index"
            hosts => "https://2e2b1e8798984f8394d843aa2ee91b6a.elasticaas.ocb.equant.com:9243"
            user => "xxx"
            password => "xxx"
            ssl => true
            cacert => "/etc/pki/orange-internal-62-server-ca.pem"
            manage_template => false
            ilm_enabled => false
            action => "create"
            index => "%{[@metadata][index]}"
        }
    }
    stdout { codex => json }
}

@Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
                .authorizeHttpRequests(authorizeHttpRequests ->
                        authorizeHttpRequests
                                .requestMatchers("/login").permitAll()
                                .anyRequest().permitAll())
                .authenticationProvider(authenticationProvider())
                .formLogin(Customizer.withDefaults())
                .build();
